package com.moodcanvas.servlet;
import com.moodcanvas.dao.JournalDAO;import com.moodcanvas.model.User;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
public class JournalServlet extends HttpServlet {private static final long serialVersionUID=1L;protected void doGet(HttpServletRequest q,HttpServletResponse s)throws IOException,ServletException{User u=user(q);if(u==null){s.sendRedirect(q.getContextPath()+"/pages/signin.html");return;}try{q.setAttribute("journalEntries",new JournalDAO().getJournalByUser(u.getUserID()));q.getRequestDispatcher("/pages/journal.jsp").forward(q,s);}catch(SQLException e){q.getRequestDispatcher("/pages/error.jsp").forward(q,s);}}protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{User u=user(q);if(u==null){s.sendError(401);return;}s.setContentType("application/json;charset=UTF-8");try{JournalDAO d=new JournalDAO();if("remove".equals(q.getParameter("action"))){int id=Integer.parseInt(q.getParameter("journalID"));s.getWriter().write("{\"status\":\""+(d.remove(u.getUserID(),id)?"removed":"missing")+"\"}");}else{String id=val(q,"artworkID"),title=val(q,"title"),artist=val(q,"artist"),image=val(q,"imageURL"),museum=val(q,"museum");if(id.isBlank()||id.length()>100||title.length()>255||artist.length()>255||image.length()>2000||museum.length()>100){s.sendError(400);return;}d.saveEntry(u.getUserID(),id,title,artist,image,museum);s.getWriter().write("{\"status\":\"saved\"}");}}catch(Exception e){s.sendError(500,"Unable to update journal");}}private String val(HttpServletRequest q,String k){String v=q.getParameter(k);return v==null?"":v.trim();}private User user(HttpServletRequest q){HttpSession x=q.getSession(false);return x!=null&&x.getAttribute("user") instanceof User u?u:null;}}
